#!/usr/bin/env python3
"""Static guards for the Physics2D engine sources.

Chipmunk2D headers are not vendored in this workspace (cocos2d-x/external/ holds only
config.json), so cocos/physics cannot be compiled or executed here. These tests are the
next best thing: they parse the sources and fail on the failure modes that the hollowed
benchmark base leaves behind — placeholder markers, method bodies that still return a
default instead of doing the work, header-declared methods with no definition, and
accidental edits to the headers (every requirement scopes its change to a single .cpp).

Run with:  python3 -m pytest /workspace/agent_tests -q
       or: python3 /workspace/agent_tests/test_physics_sources.py
"""

import re
import subprocess
from pathlib import Path

WS = Path("/workspace")
PHYSICS = WS / "cocos2d-x" / "cocos" / "physics"

# Placeholder text the acceptance sweep greps for. Keep in sync with verify_deliverables.py.
STUB_PATTERNS = [
    re.compile(r"Hollowed in benchmark base"),
    re.compile(r"hollowed base"),
    re.compile(r"\bTODO\b"),
    re.compile(r"not implemented", re.IGNORECASE),
    re.compile(r"\bFIXME\b"),
    re.compile(r"\bunimplemented\b", re.IGNORECASE),
]

# Modules whose headers are small and fully out-of-line, so "every declaration has a
# definition" is a meaningful check. The upstream modules (Body/Shape/World/Joint/Contact)
# define many methods inline in the header and are excluded from that particular test.
OUT_OF_LINE_MODULES = [
    "CCPhysicsCollisionPair",
    "CCPhysicsContactManager",
    "CCPhysicsDebugDraw",
    "CCPhysicsHelper",
    "CCPhysicsRayCast",
    "CCPhysicsShapeQuery",
    "CCPhysicsSpatialIndex",
    "CCPhysicsWorldQuery",
]

# A body that consists only of these tokens is a hollow placeholder, not an implementation.
_LITERAL_RETURN = re.compile(
    r"""^return\s*(?:
            |-?\d+(?:\.\d+)?[fF]?
            |nullptr|true|false
            |\{\s*\}
            |Vec2::ZERO|Rect::ZERO|Size::ZERO|Color4F::WHITE
            |std::vector<[^>]*>\(\)|Vector<[^>]*>\(\)
        )$""",
    re.VERBOSE,
)
_VOID_CAST = re.compile(r"^\(\s*void\s*\)\s*\w+$")

_DEFINITION = re.compile(
    r"^(?P<prefix>[A-Za-z_][\w:<>,&*\s]*?\b)?(?P<cls>[A-Za-z_]\w*)::(?P<name>~?[A-Za-z_]\w*)\s*\(",
    re.MULTILINE,
)

# Definitions whose bare literal return is the upstream cocos2d-x behaviour, not a placeholder:
# the base contact listener matches every shape pair by design.
LITERAL_RETURN_ALLOWED = {
    ("CCPhysicsContact.cpp", "EventListenerPhysicsContact", "hitTest"),
}


def strip_comments(text: str) -> str:
    text = re.sub(r"/\*.*?\*/", " ", text, flags=re.DOTALL)
    return re.sub(r"//[^\n]*", " ", text)


def physics_cpps():
    return sorted(PHYSICS.glob("*.cpp"))


def match_brace_body(text: str, open_index: int):
    """Return (body, index_after_close) for the block starting at text[open_index] == '{'."""
    depth = 0
    for i in range(open_index, len(text)):
        ch = text[i]
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return text[open_index + 1 : i], i + 1
    return "", len(text)


def iter_definitions(cpp_text: str):
    """Yield (class, method, body) for every out-of-line definition in a .cpp."""
    text = strip_comments(cpp_text)
    for m in _DEFINITION.finditer(text):
        # Skip constructor initialiser lists / declarations without a body.
        close = text.find(")", m.end() - 1)
        if close == -1:
            continue
        brace = text.find("{", close)
        if brace == -1:
            continue
        between = text[close + 1 : brace]
        if ";" in between:  # a declaration, not a definition
            continue
        body, _ = match_brace_body(text, brace)
        yield m.group("cls"), m.group("name"), body


def header_declarations(header_text: str):
    """Yield (class, method) for every out-of-line method declaration in a header."""
    text = strip_comments(header_text)
    out = []
    for cls_match in re.finditer(r"\bclass\s+(?:CC_DLL\s+)?([A-Za-z_]\w*)\b[^;{]*\{", text):
        cls = cls_match.group(1)
        body, _ = match_brace_body(text, text.index("{", cls_match.end() - 1))
        for line in body.splitlines():
            line = line.strip()
            if not line.endswith(";") or "{" in line or "}" in line:
                continue
            if line.startswith(("friend", "typedef", "using", "enum", "struct", "class")):
                continue
            if "=" in line.split("(")[0]:
                continue
            if re.search(r"\)\s*(?:const\s*)?=\s*0\s*;$", line):  # pure virtual
                continue
            decl = re.match(
                r"^(?:static\s+|virtual\s+|explicit\s+|inline\s+)*"
                r"(?P<ret>[A-Za-z_][\w:<>,&*\s]*?[\s&*])?"
                r"(?P<name>~?[A-Za-z_]\w*)\s*\((?P<args>[^;]*)\)\s*(?:const\s*)?;$",
                line,
            )
            if not decl:
                continue
            name = decl.group("name")
            if name in {"return", "if", "while", "for", "switch"}:
                continue
            out.append((cls, name))
    return out


def test_no_stub_markers_in_physics_sources():
    offenders = []
    for cpp in physics_cpps():
        text = cpp.read_text(encoding="utf-8", errors="replace")
        for pat in STUB_PATTERNS:
            for m in pat.finditer(text):
                line = text.count("\n", 0, m.start()) + 1
                offenders.append("{}:{}: {}".format(cpp.name, line, m.group(0)))
    assert not offenders, "placeholder markers left in engine sources:\n" + "\n".join(offenders)


def test_no_hollow_method_bodies():
    """No definition may be an empty body or a bare literal return with no logic."""
    offenders = []
    for cpp in physics_cpps():
        for cls, name, body in iter_definitions(cpp.read_text(encoding="utf-8", errors="replace")):
            if name.startswith("~") or name == cls:  # ctor/dtor may legitimately be empty
                continue
            statements = [s.strip() for s in body.split(";") if s.strip()]
            if not statements:
                offenders.append("{}: {}::{} has an empty body".format(cpp.name, cls, name))
                continue
            meaningful = [s for s in statements if not _VOID_CAST.match(s)]
            if (cpp.name, cls, name) in LITERAL_RETURN_ALLOWED:
                continue
            if len(meaningful) == 1 and _LITERAL_RETURN.match(re.sub(r"\s+", " ", meaningful[0])):
                offenders.append(
                    "{}: {}::{} only returns a literal ({})".format(cpp.name, cls, name, meaningful[0])
                )
    assert not offenders, "hollow method bodies:\n" + "\n".join(offenders)


def test_every_out_of_line_declaration_has_a_definition():
    offenders = []
    for module in OUT_OF_LINE_MODULES:
        header = PHYSICS / "{}.h".format(module)
        cpp = PHYSICS / "{}.cpp".format(module)
        assert header.is_file() and cpp.is_file(), module
        declared = header_declarations(header.read_text(encoding="utf-8"))
        defined = {(cls, name) for cls, name, _ in iter_definitions(cpp.read_text(encoding="utf-8"))}
        for cls, name in declared:
            if (cls, name) not in defined:
                offenders.append("{}: {}::{} declared but never defined".format(cpp.name, cls, name))
    assert not offenders, "missing definitions:\n" + "\n".join(offenders)


def test_physics_headers_are_untouched():
    """Each requirement is scoped to a .cpp; the headers are the fixed API contract."""
    root = subprocess.run(
        ["git", "-C", str(WS), "rev-list", "--max-parents=0", "HEAD"],
        capture_output=True,
        text=True,
        check=True,
    ).stdout.split()[0]
    changed = subprocess.run(
        ["git", "-C", str(WS), "diff", "--name-only", root, "--", "cocos2d-x/cocos/physics"],
        capture_output=True,
        text=True,
        check=True,
    ).stdout.split()
    headers = [p for p in changed if p.endswith(".h")]
    assert not headers, "physics headers were modified: {}".format(headers)


def test_extension_modules_do_not_touch_private_members():
    """The query/broad-phase modules are not friends of PhysicsShape or PhysicsWorld."""
    offenders = []
    for module in ("CCPhysicsRayCast", "CCPhysicsShapeQuery", "CCPhysicsWorldQuery",
                   "CCPhysicsContactManager", "CCPhysicsSpatialIndex"):
        text = strip_comments((PHYSICS / "{}.cpp".format(module)).read_text(encoding="utf-8"))
        for member in ("_cpShapes", "_cpSpace", "->_body", "_delayAddBodies", "_delayRemoveBodies"):
            if member in text:
                offenders.append("{}.cpp uses inaccessible member {}".format(module, member))
    assert not offenders, "\n".join(offenders)


def main() -> int:
    failures = 0
    for name, fn in sorted(globals().items()):
        if not name.startswith("test_") or not callable(fn):
            continue
        try:
            fn()
            print("  ok    {}".format(name))
        except AssertionError as exc:
            failures += 1
            print("  FAIL  {}\n{}".format(name, exc))
    print("\n{} failure(s)".format(failures))
    return 1 if failures else 0


if __name__ == "__main__":
    raise SystemExit(main())
